#!/usr/bin/env bash
source "$(dirname "${BASH_SOURCE[0]}")/common.sh"
need HUMAN_ROOT SIM_ROOT CUDA_VISIBLE_DEVICES
cd "$IG_ROOT"
run "$PYTHON" -m examples.baselines.act.train_act_imitator --human-root "$HUMAN_ROOT" --sim-root "$SIM_ROOT" --human-dataset-file examples/baselines/lerobot_dataset/config/exp_configs/human_train_config_15.json --sim-dataset-file examples/baselines/lerobot_dataset/config/exp_configs/sim_train_config_15.json --task-mapping-file examples/baselines/lerobot_dataset/task_mapping.json --human-task-description-file examples/baselines/lerobot_dataset/task_desc/human_desc.json --sim-task-description-file examples/baselines/lerobot_dataset/task_desc/sim_desc.json --input-mode video_only --task-encoder-type frozen_backbone --frozen-backbone-type dinov2_vitl14 --frozen-backbone-num-frames 10 --frozen-backbone-adapter-layers 1 --frozen-backbone-seq-patches 32 --pred-horizon 24 --batch-size 128 --total-epochs 10 --warmup-epochs 1 --lr 1e-4 --control-mode pd_joint_pos --hidden-dim 1024 --dim-feedforward 4096 --nheads 16 --enc-layers 12 --dec-layers 12 --save-epoch-freq 5 --num-eval-envs 1 --num-eval-episodes 1 --env-id TwoRobotPourCup-v1 --max-episode-steps 500 --no-include-depth "$@"
